import{z as o,x as s,o as l,c as h,q as n,j as r,D as B,d as e,s as A,S as i,b as E}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"位置外推评测","description":"","frontmatter":{"title":"位置外推评测","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/long-context-eval.md","filePath":"llm/long-context-eval.md","lastUpdated":1791413859000}'),m={name:"llm/long-context-eval.md"};function d(p,a,R,F,L,f){const t=s("Mermaid");return l(),h("div",null,[a[2]||(a[2]=n('<h1 id="位置外推评测" tabindex="-1">位置外推评测 <a class="header-anchor" href="#位置外推评测" aria-label="Permalink to &quot;位置外推评测&quot;">​</a></h1><div class="epigraph"><p>能把 128k 个标记送进模型，只说明掩码和位置下标没炸；能不能在这个长度上找回事实、跟上变量、做完篇章题，要另搭一套考场。</p><footer>—— 针与草堆（NIAH）、RULER、∞Bench 所划出的评测分层</footer></div><p><a href="/llm/context-length-scaling">上一课</a>指出语言建模损失随窗口下降，但幂律远弱于参数与数据；同等 FLOPs 下加长窗口会减少有效 token 数，平均 PPL 对长尾依赖也不敏感。<a href="/llm/position-extrapolation">位置插值</a> 与 <a href="/llm/yarn">YaRN</a> 把「算得动」和「相位还在支撑集里」当成第一道关。过关之后，产品仍会写出「支持 128k」。缺口是把这句话拆成递进探针：数值稳定、PPL 没崩、下游在该长度上仍可用——后两层必须靠 NIAH、RULER、∞Bench，而不是靠配置项。本课写怎么考位置外推，不把任何一种延窗方法重写一遍。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>短窗口模型在训练长度 \\(L\\) 内，注意力、<a href="/llm/rope">RoPE</a> 相位、软最大值尺度都与数据一致。推理拉到 \\(L&#39;\\) 时，失败可以来自几何（相位出界）、来自分配（熵塌到句首或句尾）、来自能力（从来没学过要用那么远的键）。这三类在损失曲线上可能长得像：都是「一长就笨」。若不拆开考，插值、温度、检索、换解码器会轮流被当成灵药。</p><p>更糟的是单一数字。只报「在 \\(L&#39;\\) 上 PPL 仍可」，会放过「中间位置的事实全部丢失」。只报 NIAH 全绿，会放过「多跳追踪和聚合在远小于 \\(L&#39;\\) 处已经垮」。评测的问题因此是：用一组难度递进的探针，把「长度」从配置改写成有效上下文——模型在哪种任务上、在多深的位置上，准确率仍高于可用阈值。<span class="marginnote">有效上下文通常短于宣称窗口。RULER 一类工作反复显示：NIAH 能过的模型，换多跳或变量追踪后，可靠长度可能打到宣称值的几分之一。宣传 128k 时，应同时报任务族和深度。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="niah-一根针、一张热力图" tabindex="-1">NIAH：一根针、一张热力图 <a class="header-anchor" href="#niah-一根针、一张热力图" aria-label="Permalink to &quot;NIAH：一根针、一张热力图&quot;">​</a></h3><p>Needle-in-a-Haystack 把一条与上下文无关的陈述（针）插入长填充（草堆）的某个深度，再在末尾提问。横轴是总长度，纵轴是针的相对深度，格子是是否找回。<span class="marginnote">术语翻译：NIAH 直译「大海捞针」——「草堆」就是几百页无关文本的堆料，「针」是里头唯一一句要找的话（如『别忘了一个秘密数字是 73905』）。跑完得到一张长×深的红绿热力图，一眼看出模型在哪段长度、哪个深度还能找回事实。</span>理想外推是整张图全绿；典型失败是：超过 \\(L\\) 立刻全红（几何崩）、只在开头和结尾绿而中间红（lost-in-the-middle）、或只有最近邻绿（窗口/滑窗模型的真实感受野）。</p><p>NIAH 考的是单点检索与位置通道是否还编码「那句话在哪」。它几乎不考推理，也不考针与草堆同分布时的干扰。作为冒烟测试极好：红了就能否定「窗口已延长」；全绿不能肯定「长上下文已可用」。</p><h3 id="ruler-合成任务把有效长度读出来" tabindex="-1">RULER：合成任务把有效长度读出来 <a class="header-anchor" href="#ruler-合成任务把有效长度读出来" aria-label="Permalink to &quot;RULER：合成任务把有效长度读出来&quot;">​</a></h3><p>RULER（Hsieh 等人）在可控长度上堆检索、多跳追踪、聚合、问答等合成题，专门对付「NIAH 过了但有效上下文虚高」。多跳要求沿一条链在长序列里跳几次；聚合要求在大量噪声项里计数或比较；变量追踪要求记住远处的绑定。准确率相对长度的曲线会给出一个有效长度：例如宣称 32k 的模型，在较难合成题上可能 8k 就开始掉。这个数字比 PPL 更接近产品体验。</p> \\[L_{\\mathrm{eff}}(\\tau)=\\max\\bigl\\{n:\\mathrm{Acc}(n)\\ge\\tau\\bigr\\} \\]<p>阈值 \\(\\tau\\) 要预先钉死（如 0.85），并按任务族分别报，否则又会退回单一数字。<span class="marginnote">数字实例：宣称 32k 的模型，取 \\(\\tau=0.85\\)，多跳任务的准确率曲线在 8k 处首次跌破 85%，那 \\(L_{\\mathrm{eff}}=8\\text{k}\\)，有效比例只有 25%。同一个模型检索题可能 \\(L_{\\mathrm{eff}}=24\\text{k}\\)。所以 RULER 的报告不是一个数，而是「每个任务族一条曲线、一个截点」。</span>RULER 的价值是把「外推成功」从布尔值变成一条随任务变难而左移的曲线。</p><h3 id="∞bench-十万以上的真实长任务" tabindex="-1">∞Bench：十万以上的真实长任务 <a class="header-anchor" href="#∞bench-十万以上的真实长任务" aria-label="Permalink to &quot;∞Bench：十万以上的真实长任务&quot;">​</a></h3><p>∞Bench（Zhang 等人）把评测推到 100k token 量级，题型贴近长书、长代码、长对话上的检索、问答、数学与调试，而不是无限可加长的合成填充。它回答的是另一句宣传：「我们能跑 100k+」之后，在真实文档结构里是否还做对。合成集可以精确控制针深；真实集不能，但能暴露分块、标题、代码作用域这些 NIAH 填不出来的结构。</p>',16)),(l(),r(i,null,{default:B(()=>[A(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E5%AE%A3%E7%A7%B0%E7%AA%97%E5%8F%A3%20L'%22%5D%20--%3E%20N%5B%22NIAH%20%E7%83%AD%E5%8A%9B%E5%9B%BE%22%5D%0A%20%20N%20--%3E%20R%5B%22RULER%20%E6%9C%89%E6%95%88%E9%95%BF%E5%BA%A6%22%5D%0A%20%20R%20--%3E%20I%5B%22%E2%88%9EBench%20%E8%B6%85%E9%95%BF%E7%9C%9F%E5%AE%9E%E4%BB%BB%E5%8A%A1%22%5D%0A%20%20N%20--%3E%7C%22%E5%85%A8%E7%BA%A2%22%7C%20X%5B%22%E5%87%A0%E4%BD%95%E6%88%96%E6%B1%87%E7%82%B9%E5%A4%B1%E8%B4%A5%22%5D%0A%20%20R%20--%3E%7C%22%E8%BF%9C%E5%B0%8F%E4%BA%8E%20L'%22%7C%20Y%5B%22%E6%A3%80%E7%B4%A2%E8%BF%87%E5%85%B3%E3%80%81%E5%A4%9A%E8%B7%B3%E4%B8%8D%E5%A4%9F%22%5D%0A%20%20I%20--%3E%7C%22%E4%BB%8D%E5%B7%AE%22%7C%20Z%5B%22%E7%BC%BA%E7%9A%84%E6%98%AF%E8%AE%B0%E5%BF%86%E4%B8%8E%E7%BB%93%E6%9E%84%EF%BC%8C%E4%B8%8D%E6%98%AF%E4%B8%8B%E6%A0%87%22%5D%0A"})]),fallback:B(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"位置外推评测能分开失败型，是因为不同探针碰到的是不同通道。NIAH 几乎只要求：查询与针的键在点积上仍能赢过草堆，且针的位置下标没有把 RoPE 转成噪声。若 PI / YaRN / 距离封顶把相位拉回支撑集，NIAH 往往先变绿。RULER 的多跳还要求中间结果在很长的干扰下不被覆盖，这已经是工作记忆与注意力熵的问题，相位正确也不够。∞Bench 再叠加文档先验：模型必须在训练里见过类似的长程结构，或在推理时用压缩、检索、分块去造结构。",-1)),a[5]||(a[5]=E("p",null,"因此「外推评测」不是单一基准的别名，而是一条证据链。PPL 随长度的曲线仍要画：它便宜，能抓住数值爆炸和全面崩溃。但不能停在 PPL。长度 \\(n\\) 上的损失",-1)),a[6]||(a[6]=e(" \\[\\mathrm{PPL}(n)=\\exp\\Bigl(\\tfrac{1}{n}\\sum_{t}\\ell_t\\Bigr) \\]",-1)),a[7]||(a[7]=E("p",null,[e("会把「只有 1% 的 token 需要长程」平均掉；那些 token 恰恰是用户在意的针。"),E("span",{class:"marginnote"},"同一条 YaRN 续训，PPL 平滑、NIAH 全绿、RULER 有效长度只有宣称值一半——这不是评测打架，而是三层关卡都该写进报告。只摘最绿的那张图，等于没评外推。")],-1)),a[8]||(a[8]=E("p",null,"深度也很关键。针插在开头、中间、结尾，对应汇点偏置、lost-in-the-middle、近邻偏置。热力图比「平均准确率」多一个维度，能直接指向该换温度、该留 sink，还是该改位置编码。把失败形态翻译成下一步动作：",-1)),(l(),r(i,null,{default:B(()=>[A(t,{id:"mermaid-61",class:"mermaid",graph:"flowchart%20TD%0A%20%20F1%5B%22%E8%B6%85%E8%BF%87%20L'%20%E7%AB%8B%E5%88%BB%E5%85%A8%E7%BA%A2%3Cbr%2F%3ERoPE%20%E7%9B%B8%E4%BD%8D%E5%87%BA%E7%95%8C%22%5D%20--%3E%20C1%5B%22%E6%94%B9%E6%8F%92%E5%80%BC%20%2F%20YaRN%20%2F%20%E5%9F%BA%E6%95%B0%22%5D%0A%20%20F2%5B%22%E5%A4%B4%E5%B0%BE%E7%BB%BF%2C%20%E4%B8%AD%E9%97%B4%E7%BA%A2%3Cbr%2F%3Elost-in-the-middle%22%5D%20--%3E%20C2%5B%22%E6%9F%A5%E6%B3%A8%E6%84%8F%E5%8A%9B%E7%86%B5%E4%B8%8E%E6%B1%87%E7%82%B9%22%5D%0A%20%20F3%5B%22%E5%8F%AA%E6%9C%89%E8%BF%91%E9%82%BB%E7%BB%BF%3Cbr%2F%3E%E7%9C%9F%E5%AE%9E%E6%84%9F%E5%8F%97%E9%87%8E%E6%B2%A1%E6%89%93%E5%BC%80%22%5D%20--%3E%20C3%5B%22%E6%A3%80%E6%9F%A5%E6%BB%91%E7%AA%97%20%2F%20%E7%A8%80%E7%96%8F%E6%8E%A9%E7%A0%81%E9%85%8D%E7%BD%AE%22%5D%0A%20%20F4%5B%22NIAH%20%E5%85%A8%E7%BB%BF%2C%20RULER%20%E6%8E%89%3Cbr%2F%3E%E5%A4%9A%E8%B7%B3%E5%B7%A5%E4%BD%9C%E8%AE%B0%E5%BF%86%E4%B8%8D%E8%B6%B3%22%5D%20--%3E%20C4%5B%22%E8%A1%A5%E9%95%BF%E7%A8%8B%E4%BB%BB%E5%8A%A1%E7%BB%AD%E8%AE%AD%3Cbr%2F%3E%E4%B8%8D%E6%98%AF%E6%94%B9%E5%87%A0%E4%BD%95%22%5D%0A"})]),fallback:B(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[9]||(a[9]=n('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>合成任务可以无限加长，真实任务有版权、清洗和长度分布问题；∞Bench 再长也覆盖不了所有产品文档。内部评测仍应加一条与业务同分布的长文档集，否则会出现「三个公开榜都好看、合同条款检索仍瞎」的缝。</p><p>评测成本随 \\(n\\) 线性到二次膨胀。每次改 RoPE 基数就跑全套 ∞Bench 不现实。合理的门禁是：提交前 NIAH 热力图必跑，RULER 抽一两个难任务看 \\(L_{\\mathrm{eff}}\\) 有没有回归，长真实集放在发布前。<span class="marginnote">直觉类比：这套分层像体检流程——NIAH 是挂号时量体温，便宜、每次都做，坏了立刻拦下；RULER 是专项血检，抽两项盯回归；∞Bench 是全套影像，只在发布前做一次。把影像塞进每次提交，门禁会慢到没人等它。</span>不要用「能完成 128k 前向」当作 CI 绿灯。</p><p>另一边界：训练已经是长窗口的模型，与短训再外推的模型，应分开表。前者的 NIAH 失败更像数据或注意力设计问题；后者才是位置外推。混在一张排行榜里会让 YaRN 与原生 128k 预训练看起来像同一项技术。<span class="marginnote">针的措辞、草堆是否含干扰事实、提问是否泄漏格式，都会让 NIAH 虚高。评测规范要冻结针模板和随机种子，否则「我们的热力图更绿」可能只是针更好找。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>宣称窗口只保证能前向；有效上下文必须按任务族和针深来测。</li><li>NIAH 是检索冒烟测试，全红能否定延窗，全绿不能肯定可用。</li><li>RULER 用多跳、聚合、追踪把有效长度 \\(L_{\\mathrm{eff}}\\) 读成一条随难度左移的曲线。</li><li>∞Bench 覆盖 100k 以上更接近真实文档与代码的任务，补合成集没有的结构。</li><li>PPL、NIAH、RULER、真实长任务是递进证据，不可互相替代。</li><li>热力图的深度维能区分相位失败、中间丢失与近邻偏置。</li><li>出处：Kamradt 的 NIAH 设定（2023 起被广泛采用）；Hsieh 等，<em>RULER</em>，2024；Zhang 等，<em>∞Bench</em>，2024。延窗方法本身见 YaRN、位置插值与后文流式 / 分组方案。</li></ul>',6))])}const u=o(m,[["render",d]]);export{c as __pageData,u as default};
